arguments.command:
cd /app; echo "blank lines:"; grep -c '^$' primers.fasta; echo "line count:"; wc -l < primers.fasta; echo; python3 - << 'PY'
import subprocess
F=['-tp','1','-sc','1','-mv','50','-dv','2','-n','0.8','-d','500']
def tm(s):return float(subprocess.run(['oligotm']+F+[s],capture_output=True,text=True).stdout)
d={}
for l in open('primers.fasta'):
    l=l.strip()
    if l[0]=='>':k=l[1:]
    else:d[k]=l
for name in ['input','egfp','flag','snap']:
    f=d[name+'_fwd'][17:]; r=d[name+'_rev'][17:]
    print(f"{name}: fwd len{len(f)} Tm{tm(f):.2f} | rev len{len(r)} Tm{tm(r):.2f} | diff{abs(tm(f)-tm(r)):.2f}")
PY

